// 2. LabelWidget
// =============================================================================
test.describe('LabelWidget', () => {
  test('Left aligned label has text-align left', async ({ page }) => {
    const section = page.locator('.widget-section').nth(1);
    const labels = section.locator('.label-widget');
    const firstLabel = labels.first();
    await expect(firstLabel).toBeVisible();
    const textAlign = await firstLabel.evaluate(el => window.getComputedStyle(el).textAlign);
    expect(textAlign).toBe('left');
    await page.screenshot({ path: 'test-results/manual/ch16-widgets/primitives/evidence/screenshot-7-label-left.png' });
  });

  test('Center aligned label has text-align center and color #88ccff', async ({ page }) => {
    const section = page.locator('.widget-section').nth(1);
    const labels = section.locator('.label-widget');
    const centerLabel = labels.nth(1);
    await expect(centerLabel).toBeVisible();
    const textAlign = await centerLabel.evaluate(el => window.getComputedStyle(el).textAlign);
    expect(textAlign).toBe('center');
    const color = await centerLabel.evaluate(el => window.getComputedStyle(el).color);
    // #88ccff in RGB
    expect(color).toMatch(/rgb\(13[0-9], 20[0-9], 25[0-9]\)/);
    await page.screenshot({ path: 'test-results/manual/ch16-widgets/primitives/evidence/screenshot-8-label-center.png' });
  });

  test('Right aligned label has text-align right and color #ffcc88', async ({ page }) => {
    const section = page.locator('.widget-section').nth(1);
    const labels = section.locator('.label-widget');
    const rightLabel = labels.nth(2);
    await expect(rightLabel).toBeVisible();
    const textAlign = await rightLabel.evaluate(el => window.getComputedStyle(el).textAlign);
    expect(textAlign).toBe('right');
    const color = await rightLabel.evaluate(el => window.getComputedStyle(el).color);
    expect(color).toMatch(/rgb\(25[0-9], 20[0-9], 13[0-9]\)/);
  });

  test('Contrast text has text-shadow halo effect', async ({ page }) => {
    const section = page.locator('.widget-section').nth(1);
    const labels = section.locator('.label-widget');
    const contrastLabel = labels.nth(3);
    await expect(contrastLabel).toContainText('Contrast');
    const shadow = await contrastLabel.evaluate(el => window.getComputedStyle(el).textShadow);
    expect(shadow).not.toBe('none');
    // Should contain multiple offset values (comma-separated for 4-directional)
    expect(shadow.split(',').length).toBeGreaterThan(1);
    await page.screenshot({ path: 'test-results/manual/ch16-widgets/primitives/evidence/screenshot-9-label-contrast.png' });
  });

  test('Shadow text has diagonal text-shadow', async ({ page }) => {
    const section = page.locator('.widget-section').nth(1);
    const labels = section.locator('.label-widget');
    const shadowLabel = labels.nth(4);
    await expect(shadowLabel).toContainText('Shadow');
    const shadow = await shadowLabel.evaluate(el => window.getComputedStyle(el).textShadow);
    expect(shadow).not.toBe('none');
    await page.screenshot({ path: 'test-results/manual/ch16-widgets/primitives/evidence/screenshot-10-label-shadow.png' });
  });
});

