// 10. DropDownButtonWidget
// =============================================================================
test.describe('DropDownButtonWidget', () => {
  test('Dropdown shows as closed initially', async ({ page }) => {
    await expect(page.locator('#dd-status')).toContainText('关闭');
    await page.screenshot({ path: 'test-results/manual/ch16-widgets/primitives/evidence/screenshot-28-dropdown-closed.png' });
  });

  test('Clicking dropdown button fires onClick callback (status changes)', async ({ page }) => {
    const ddBtn = page.locator('[data-widget-id="dd-demo"]');
    await ddBtn.click();
    await page.waitForTimeout(400);

    // Status should reflect that onClick fired
    await expect(page.locator('#dd-status')).not.toHaveText('关闭');

    // Close the dropdown for subsequent tests
    await ddBtn.click();
    await page.waitForTimeout(300);

    await page.screenshot({ path: 'test-results/manual/ch16-widgets/primitives/evidence/screenshot-29-dropdown-open.png' });
  });

  test('DropDownButton text is visible and not empty', async ({ page }) => {
    const ddBtn = page.locator('[data-widget-id="dd-demo"]');
    await expect(ddBtn).toBeVisible();
    const text = await ddBtn.textContent();
    expect(text).toBeTruthy();
    expect(text!.length).toBeGreaterThan(0);
    await page.screenshot({ path: 'test-results/manual/ch16-widgets/primitives/evidence/screenshot-30-dropdown-visible.png' });
  });

  test('Clicking dropdown again toggles state (close)', async ({ page }) => {
    // First click: open
    const ddBtn = page.locator('[data-widget-id="dd-demo"]');
    await ddBtn.click();
    await page.waitForTimeout(300);

    // Second click: should close
    await ddBtn.click();
    await page.waitForTimeout(300);

    // Status should be back to closed
    await expect(page.locator('#dd-status')).toContainText('关闭');
    await page.screenshot({ path: 'test-results/manual/ch16-widgets/primitives/evidence/screenshot-31-dropdown-close.png' });
  });

  test('Pressing Escape on dropdown button is handled (no crash)', async ({ page }) => {
    // Press Escape on the page - should not crash
    await page.keyboard.press('Escape');
    await page.waitForTimeout(300);
    // Page should still be functional
    await expect(page.locator('#info-ua')).toBeVisible();
    await page.screenshot({ path: 'test-results/manual/ch16-widgets/primitives/evidence/screenshot-32-dropdown-escape.png' });
  });
});
